INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > MongoDB > Dokumentenmodellierung
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Werden Dokumente in MongoDB hauptsächlich im JSON- oder BSON-Format gespeichert?', 2, '[{"text": "Ja", "correct": true, "because": "MongoDB nutzt BSON intern"}, {"text": "Nein", "correct": false, "because": "JSON/BSON ist Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Können eingebettete Dokumente in MongoDB hierarchische Datenstrukturen darstellen?', 2, '[{"text": "Ja", "correct": true, "because": "Eingebettete Dokumente ermöglichen Hierarchien"}, {"text": "Nein", "correct": false, "because": "Zweck von Embedded Documents"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Referenzen zwischen Dokumenten in MongoDB ähnlich wie Fremdschlüssel in relationalen Datenbanken?', 2, '[{"text": "Ja", "correct": true, "because": "Referenzen verknüpfen Dokumente"}, {"text": "Nein", "correct": false, "because": "Ähnlich, aber flexibler"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Schemaflexibilität in MongoDB so groß, dass jedes Dokument einer Collection ein anderes Schema haben kann?', 2, '[{"text": "Ja", "correct": true, "because": "MongoDB erlaubt flexible Schemata"}, {"text": "Nein", "correct": false, "because": "Schemaflexibilität ist Kernmerkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen eingebettete Dokumente in MongoDB immer die gleiche Struktur wie das Hauptdokument haben?', 2, '[{"text": "Nein", "correct": true, "because": "Eingebettete Dokumente sind flexibel"}, {"text": "Ja", "correct": false, "because": "Keine feste Struktur erforderlich"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'In welchem Format werden Dokumente in MongoDB intern gespeichert?', 2, '[{"text": "BSON", "correct": true, "because": "Binäres JSON für Effizienz"}, {"text": "XML", "correct": false, "because": "Nicht verwendet"}, {"text": "CSV", "correct": false, "because": "Tabellenformat"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik wird in MongoDB verwendet, um hierarchische Daten innerhalb eines Dokuments zu speichern?', 3, '[{"text": "Eingebettete Dokumente", "correct": true, "because": "Für verschachtelte Strukturen"}, {"text": "Referenzen", "correct": false, "because": "Verknüpfung, nicht Einbettung"}, {"text": "Tabellen", "correct": false, "because": "Relationale Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie werden Beziehungen zwischen Dokumenten in MongoDB oft modelliert, wenn sie nicht eingebettet sind?', 2, '[{"text": "Referenzen", "correct": true, "because": "Verknüpfung über IDs"}, {"text": "Eingebettete Arrays", "correct": false, "because": "Für Hierarchien"}, {"text": "Primärschlüssel", "correct": false, "because": "Relationale DB"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal von MongoDB ermöglicht es, Dokumente ohne festes Schema zu speichern?', 2, '[{"text": "Schemaflexibilität", "correct": true, "because": "Keine starre Struktur"}, {"text": "Referentielle Integrität", "correct": false, "because": "Relationale Eigenschaft"}, {"text": "Atomarität", "correct": false, "because": "Transaktionseigenschaft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Modellierungstechnik reduziert die Notwendigkeit für Joins in MongoDB?', 2, '[{"text": "Eingebettete Dokumente", "correct": true, "because": "Daten in einem Dokument"}, {"text": "Referenzen", "correct": false, "because": "Erfordert Joins"}, {"text": "Tabellen", "correct": false, "because": "Nicht MongoDB"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften haben Dokumente in MongoDB?', 4, '[{"text": "JSON/BSON-Format", "correct": true, "because": "Standardformat"}, {"text": "Flexible Struktur", "correct": true, "because": "Schemafreiheit"}, {"text": "Eingebettete Dokumente", "correct": true, "because": "Hierarchische Daten"}, {"text": "Feste Spalten", "correct": false, "because": "Relationale DB"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten eingebettete Dokumente in MongoDB?', 3, '[{"text": "Schneller Zugriff", "correct": true, "because": "Keine Joins nötig"}, {"text": "Hierarchische Darstellung", "correct": true, "because": "Verschachtelte Struktur"}, {"text": "Datenlokalisierung", "correct": true, "because": "Alles in einem Dokument"}, {"text": "Automatische Eindeutigkeit", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden gibt es zur Modellierung von Beziehungen in MongoDB?', 4, '[{"text": "Eingebettete Dokumente", "correct": true, "because": "Für Hierarchien"}, {"text": "Referenzen", "correct": true, "because": "Für Verknüpfungen"}, {"text": "Manuelle IDs", "correct": true, "because": "Referenzielle Verknüpfung"}, {"text": "Tabellenjoins", "correct": false, "because": "Relationale DB"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale beschreiben die Schemaflexibilität in MongoDB?', 3, '[{"text": "Unterschiedliche Dokumentstrukturen", "correct": true, "because": "Keine feste Struktur"}, {"text": "Dynamische Anpassung", "correct": true, "because": "Änderungen ohne Schema"}, {"text": "Keine Validierung nötig", "correct": true, "because": "Optional, nicht zwingend"}, {"text": "Feste Spaltenanzahl", "correct": false, "because": "Relationale DB"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sind bei der Dokumentenmodellierung in MongoDB zu berücksichtigen?', 3, '[{"text": "Datenhäufigkeit", "correct": true, "because": "Eingebettet vs. Referenz"}, {"text": "Zugriffsmuster", "correct": true, "because": "Effizienz optimieren"}, {"text": "Datengröße", "correct": true, "because": "Eingebettete Dokumente begrenzen"}, {"text": "Tabellenstruktur", "correct": false, "because": "Nicht MongoDB"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Dokumente in MongoDB werden in BSON gespeichert. b) Sie erfordern ein festes Schema.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "BSON ja, Schema nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eingebettete Dokumente ermöglichen schnelle Abfragen. b) Sie sind immer flache Strukturen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schnell ja, flach nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Referenzen verknüpfen Dokumente über IDs. b) Sie sind effizienter als eingebettete Dokumente.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verknüpfung ja, Effizienz abhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Schemaflexibilität erlaubt unterschiedliche Dokumentstrukturen. b) Jedes Dokument muss ein festes Schema haben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Flexibilität ja, fest nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eingebettete Dokumente reduzieren Joins. b) Referenzen sind für kleine Datenmengen ideal.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Joins ja, Referenzen bei großen Mengen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

